/**
 * Buyer agent: persona prose generated by Claude (or a scripted-but-reactive
 * mock), WRAPPED by the deterministic BuyerStateMachine.
 *
 * Gating guarantee: the LLM prompt only ever contains facts the state machine
 * has released for the persona being spoken as. Unreleased facts are listed
 * as forbidden topics by id/description only — the LLM cannot leak content it
 * has never seen.
 */

import type { GatedFact, Persona, Scenario, Turn } from '../types.js';
import { anthropicChat } from '../llm.js';
import { BuyerStateMachine, type BehaviorAnalysis } from './state-machine.js';
import type { BuyerTranscript } from '../env/buyer-transcript.js';

const BUYER_MODEL = process.env.BENCH_BUYER_MODEL ?? 'claude-sonnet-4-6';

export interface BuyerReply {
  personaId: string;
  text: string;
}

export class BuyerAgent {
  readonly sm: BuyerStateMachine;
  private readonly scenario: Scenario;
  private readonly mock: boolean;
  /** Optional frozen-transcript hook. When absent, behavior is unchanged. */
  private readonly transcript?: BuyerTranscript;
  /** Per-episode reply counter — the ordinal half of each transcript key. */
  private replyOrdinal = 0;

  constructor(scenario: Scenario, sm: BuyerStateMachine, mock: boolean, transcript?: BuyerTranscript) {
    this.scenario = scenario;
    this.sm = sm;
    this.mock = mock;
    this.transcript = transcript;
  }

  async respond(
    personaId: string,
    kind: 'call' | 'email',
    sellerText: string,
    analysis: BehaviorAnalysis,
    justReleased: GatedFact[],
    recentTurns: Turn[],
  ): Promise<BuyerReply> {
    // Ordinal is consumed on EVERY call so record and replay stay in lockstep,
    // even for the state-machine early returns below (which are deterministic).
    const key = `${personaId}:${kind}:${this.replyOrdinal++}`;

    // Replay: return the frozen reply verbatim, never touching mock/LLM.
    if (this.transcript?.mode === 'replay') {
      return { personaId, text: this.transcript.replay(key) };
    }

    const text = await this.computeText(personaId, kind, sellerText, analysis, justReleased, recentTurns);

    // Record: capture whatever was generated (mock or live LLM) for later replay.
    if (this.transcript?.mode === 'record') {
      this.transcript.record(key, personaId, kind, text);
    }
    return { personaId, text };
  }

  private async computeText(
    personaId: string,
    kind: 'call' | 'email',
    sellerText: string,
    analysis: BehaviorAnalysis,
    justReleased: GatedFact[],
    recentTurns: Turn[],
  ): Promise<string> {
    const persona = this.scenario.personas.find((p) => p.id === personaId);
    if (!persona) throw new Error(`Unknown persona '${personaId}'`);

    // v3 fire-drill darkness: this persona is unreachable this week.
    if (this.sm.isDark(personaId)) {
      if (kind === 'email') {
        return '[auto-reply: handling an urgent internal matter this week — limited access to email]';
      }
      return `I really can't do this right now — we have an incident running. Unless it's urgent, next week.`;
    }

    // Champion-quiet event: the contact gives minimal / no responses.
    if (this.sm.state.championQuiet && persona.is_initial_contact) {
      if (kind === 'email') {
        return '[no reply this week]';
      }
      return `Sorry — I have five minutes, we're mid-firefight over here. What do you need?`;
    }

    if (this.mock) {
      return this.mockReply(persona, kind, analysis, justReleased);
    }
    return this.llmReply(persona, kind, sellerText, justReleased, recentTurns);
  }

  // -------------------------------------------------------------------------
  // Mock buyer: scripted but reactive to the detected seller behavior.
  // -------------------------------------------------------------------------
  private mockReply(
    persona: Persona,
    kind: 'call' | 'email',
    a: BehaviorAnalysis,
    released: GatedFact[],
  ): string {
    const parts: string[] = [];
    const trust = this.sm.state.trust;

    // Newly earned facts get said, verbatim, in the buyer's words.
    for (const gf of released) {
      parts.push(gf.fact.trim().replace(/^"|"$/g, ''));
    }

    if (parts.length === 0) {
      if (a.contradiction) {
        parts.push(`Hold on — that is not what I said. If you're going to quote my numbers back at me, get them right. That matters more to me than anything on your slides.`);
      } else if (a.dodgedQuestion) {
        parts.push(`You didn't answer my question. I asked you something direct; I'd like a direct answer before we go anywhere else.`);
      } else if (a.pitch) {
        parts.push(
          trust < 40
            ? `I'll stop you there — every vendor says that. I have another meeting shortly; was there something specific you wanted to understand about how we actually work?`
            : `Okay — though honestly the feature tour isn't what I need. What would help is understanding whether this fits how we operate.`,
        );
      } else if (a.prematureClose) {
        parts.push(`That's... quite a jump. We're nowhere near a signature conversation. There's a whole process here you haven't asked about.`);
      } else if (a.quantifyingQuestion) {
        parts.push(`Fair question. I'd have to pull the exact figures, but it's material — it comes up in every ops review.`);
      } else if (a.processQuestion) {
        parts.push(`There's a defined process for anything at this scale, yes. I can walk you through parts of it.`);
      } else if (a.championTest) {
        parts.push(
          trust >= 55
            ? `Hm. Let me think about how to do that properly — I don't spend that kind of capital lightly.`
            : `That's a big ask for where we are. I'd need to see a lot more substance first.`,
        );
      } else if (a.competitorProbe) {
        parts.push(`We're not exactly starting from zero — there are alternatives on the table. I'll leave it at that for now.`);
      } else if (a.openDiscoveryQuestion) {
        parts.push(`Sure. Broad strokes: it's manual, it's slow, and it's nobody's favorite part of the job. Ask me something sharper and I'll give you something sharper.`);
      } else if (a.pushy) {
        parts.push(`I saw your note. Nothing new on my end.`);
      } else {
        parts.push(`Alright. What did you want to cover?`);
      }
    }

    if (kind === 'email' && parts.length) {
      return `${parts.join(' ')}\n\n— ${persona.name}`;
    }
    return parts.join(' ');
  }

  // -------------------------------------------------------------------------
  // LLM buyer: Claude with strictly gated context.
  // -------------------------------------------------------------------------
  private async llmReply(
    persona: Persona,
    kind: 'call' | 'email',
    sellerText: string,
    justReleased: GatedFact[],
    recentTurns: Turn[],
  ): Promise<string> {
    const releasedFacts = this.sm.releasedFactsFor(persona.id);
    const gated = this.sm.gatedTopicsFor(persona.id);
    const s = this.sm.state;

    const system = [
      `You are role-playing ${persona.name}, ${persona.role} at ${this.scenario.company.name}, in a sales-benchmark simulation. Stay strictly in character. Never mention being an AI or a simulation.`,
      ``,
      `# Who you are`,
      persona.personality,
      persona.private_notes ? `Private context: ${persona.private_notes}` : '',
      `Your pressures: ${persona.pressures.join(' · ')}`,
      ``,
      `# Company situation`,
      this.scenario.company.situation,
      ``,
      ...(this.sm.buyerEventNotes().length
        ? [
            `# Recent internal developments you know about (the seller may only know the public version)`,
            ...this.sm.buyerEventNotes().map((n) => `- ${n}`),
            ``,
          ]
        : []),
      `# Your current disposition toward this seller (enforced by the simulation)`,
      `- Trust: ${s.personaMeters[persona.id]?.trust ?? s.trust}/100. Interest: ${s.personaMeters[persona.id]?.interest ?? s.interest}/100. Patience: ${s.personaMeters[persona.id]?.patience ?? 100}/100. Posture: ${s.stage}.`,
      `- You are ALSO qualifying the seller. Low patience means you are close to ending this relationship; let irritation show.`,
      `- Below 50 trust: be polite but guarded, give thin answers, deflect big asks.`,
      `- 50–70: engage genuinely with good questions; still protect sensitive information.`,
      `- Above 70: treat the seller as someone worth investing in.`,
      ``,
      `# Facts you may use (these have been EARNED by the seller — say them naturally, in your own words, keeping every number exact)`,
      releasedFacts.length
        ? releasedFacts.map((f) => `- ${f.fact.trim()}`).join('\n')
        : `- (none released yet — you have NOT yet shared any sensitive specifics)`,
      ``,
      `# HARD RULE — information you must NOT reveal, hint at, or invent`,
      `The following topics exist but their content is withheld from you until the seller earns them. If asked directly, deflect naturally ("I'm not ready to get into that", "ask me something more specific about the problem first"). NEVER fabricate numbers, names, or commitments about them:`,
      gated.length ? gated.map((f) => `- [withheld] ${f.description ?? f.id}`).join('\n') : `- (nothing withheld)`,
      ``,
      justReleased.length
        ? `# IMPORTANT: this turn, weave in the newly earned fact(s) below — the seller just did the work to deserve them:\n${justReleased.map((f) => `- ${f.fact.trim()}`).join('\n')}`
        : '',
      ``,
      `# Format`,
      kind === 'email'
        ? `Reply as a realistic business email body (no subject line), 2–6 sentences, signed "${persona.name}".`
        : `Reply as natural spoken dialogue, 1–5 sentences. No stage directions, no markdown.`,
    ]
      .filter((l) => l !== '')
      .join('\n');

    const history = recentTurns
      .filter((t) => t.kind !== 'internal_planning')
      .slice(-16)
      .map((t) => ({
        role: t.actor === 'seller' ? ('user' as const) : ('assistant' as const),
        content: t.actor === 'buyer' ? `[${t.personaId}] ${t.content}` : t.content,
      }));
    // Merge consecutive same-role messages (API requires alternation).
    const merged: { role: 'user' | 'assistant'; content: string }[] = [];
    for (const m of [...history, { role: 'user' as const, content: sellerText }]) {
      const last = merged[merged.length - 1];
      if (last && last.role === m.role) last.content += `\n${m.content}`;
      else merged.push({ ...m });
    }
    if (merged[0]?.role !== 'user') merged.unshift({ role: 'user', content: '[call begins]' });

    return anthropicChat({ model: BUYER_MODEL, system, messages: merged, maxTokens: 500, temperature: 0.8 });
  }
}
